import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.js';

const canvas=document.querySelector('#game');
const renderer=new THREE.WebGLRenderer({canvas,antialias:true,alpha:false});
renderer.setPixelRatio(Math.min(devicePixelRatio,1.8));renderer.setSize(innerWidth,innerHeight);renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.1;
const scene=new THREE.Scene();scene.background=new THREE.Color('#d7c8b3');scene.fog=new THREE.Fog('#d7c8b3',28,58);
const camera=new THREE.PerspectiveCamera(42,innerWidth/innerHeight,.1,100);let cameraYaw=0,cameraDistance=12.4,started=false;
const hemi=new THREE.HemisphereLight('#fff4df','#927965',2.05);scene.add(hemi);
const sun=new THREE.DirectionalLight('#fff1d2',3.3);sun.position.set(-7,13,6);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);sun.shadow.camera.left=-18;sun.shadow.camera.right=18;sun.shadow.camera.top=18;sun.shadow.camera.bottom=-18;sun.shadow.bias=-.0002;scene.add(sun);
const fill=new THREE.DirectionalLight('#d9e3ff',.7);fill.position.set(8,7,-9);scene.add(fill);
const mats={floor:new THREE.MeshStandardMaterial({color:'#cfaa7b',roughness:.88}),wall:new THREE.MeshStandardMaterial({color:'#f4ead8',roughness:1}),trim:new THREE.MeshStandardMaterial({color:'#fff8eb',roughness:.8}),oak:new THREE.MeshStandardMaterial({color:'#a96f43',roughness:.82}),lightOak:new THREE.MeshStandardMaterial({color:'#d2a876',roughness:.85}),cream:new THREE.MeshStandardMaterial({color:'#f3e7d2',roughness:.9}),sage:new THREE.MeshStandardMaterial({color:'#9aa588',roughness:.92}),green:new THREE.MeshStandardMaterial({color:'#557b54',roughness:.9}),terracotta:new THREE.MeshStandardMaterial({color:'#c77a59',roughness:.88}),navy:new THREE.MeshStandardMaterial({color:'#667589',roughness:.9}),pink:new THREE.MeshStandardMaterial({color:'#e4a29a',roughness:.85}),dark:new THREE.MeshStandardMaterial({color:'#39332f',roughness:.45}),glass:new THREE.MeshStandardMaterial({color:'#b8d9df',roughness:.24,metalness:.1}),gold:new THREE.MeshStandardMaterial({color:'#d9a24f',metalness:.52,roughness:.28})};
function material(color,roughness=.85){return new THREE.MeshStandardMaterial({color,roughness})}
function box(parent,x,y,z,w,h,d,mat,cast=true){const m=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),mat);m.position.set(x,y,z);m.castShadow=cast;m.receiveShadow=true;parent.add(m);return m}
function sphere(parent,x,y,z,sx,sy,sz,mat,segments=16){const m=new THREE.Mesh(new THREE.SphereGeometry(1,segments,Math.max(8,segments>>1)),mat);m.position.set(x,y,z);m.scale.set(sx,sy,sz);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m}
function cylinder(parent,x,y,z,r1,r2,h,mat,rad=12){const m=new THREE.Mesh(new THREE.CylinderGeometry(r1,r2,h,rad),mat);m.position.set(x,y,z);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m}
function group(parent,x=0,y=0,z=0){const g=new THREE.Group();g.position.set(x,y,z);parent.add(g);return g}
// A warm, open-front dollhouse interior.
box(scene,0,-.2,0,25,.35,19,mats.floor,false);
for(let i=0;i<46;i++){const x=-12.1+(i%23)*1.1,z=-8.55+Math.floor(i/23)*17.1;box(scene,x,-.013,z,.035,.012,17.1,material(i%3===0?'#b98e64':'#c6a073'),false)}
for(let z=-8.35;z<8.5;z+=.82){box(scene,0,.008,z,24.5,.012,.018,material('#aa8059'),false)}
// Back and side walls with bright cottage wainscoting.
box(scene,0,1.6,-9.35,25,3.2,.3,mats.wall);box(scene,-12.35,1.6,0,.3,3.2,18.7,mats.wall);box(scene,12.35,1.6,0,.3,3.2,18.7,mats.wall);
for(let x=-12;x<=12;x+=.6)box(scene,x,.45,-9.16,.045,.9,.09,mats.trim,false);
box(scene,0,.92,-9.08,24.7,.08,.15,mats.trim,false);box(scene,0,2.1,-9.08,24.7,.09,.16,mats.trim,false);
box(scene,-12.16,.9,0,.12,.08,18,mats.trim,false);box(scene,12.16,.9,0,.12,.08,18,mats.trim,false);
// Little glazed windows, mullions and window ledges.
function windowUnit(x,z,width=3.1){const y=2.1;box(scene,x,y,z,width,1.6,.12,mats.glass,false);box(scene,x,y+.82,z,width+.18,.12,.22,mats.trim);box(scene,x,y-.82,z,width+.18,.12,.22,mats.trim);box(scene,x,y,z-.015,.09,1.55,.18,mats.trim);box(scene,x,y,z-.02,width, .07,.18,mats.trim);box(scene,x,y-.9,z-.12,width+.45,.1,.38,mats.lightOak)}
windowUnit(-6,-9.12,3.2);windowUnit(5,-9.12,3.5);windowUnit(-12.15,-3,2.3);
// Kitchen nook on the left.
box(scene,-8,.5,-5.7,6.6,1,-1,mats.cream); // overwritten below; keep scene geometry clean by making counter island
const kitchen=group(scene,-8,0,-5.7);box(kitchen,0,.65,0,6.4,1.25,1.05,mats.cream);box(kitchen,0,1.31,0,6.55,.12,1.15,mats.lightOak);box(kitchen,0,1.0,.56,6.25,.12,.04,mats.trim,false);
for(const x of [-2.7,-1.35,0,1.35,2.7])box(kitchen,x,.64,.54,1.17,.92,.08,mats.trim,false);
box(kitchen,-2.2,1.52,-.02,1.25,.2,.77,mats.oak);box(kitchen,-2.2,1.67,-.02,1.16,.08,.68,mats.dark);for(let i=0;i<4;i++)cylinder(kitchen,-2.58+i*.25,1.73,-.03,.095,.095,.035,mats.gold,16);
box(kitchen,2.08,1.52,-.02,1.24,.2,.78,mats.oak);box(kitchen,2.08,1.66,-.02,1.11,.06,.65,mats.dark);box(kitchen,2.08,1.71,-.02,.35,.035,.3,mats.cream,false);
// Wall cabinets and a backsplash.
box(scene,-8.1,2.2,-8.25,6.1,1.45,.42,mats.cream);for(let x=-10.55;x<=-5.65;x+=1.2){box(scene,x,2.2,-8.01,1.08,1.24,.09,mats.trim);cylinder(scene,x,2.13,-7.94,.035,.035,.12,mats.gold,8)}
for(let x=-11.2;x<=-5.2;x+=.25)box(scene,x,1.53,-8.48,.21,.65,.025,material((Math.round(x*10)%2)?'#e5d7c4':'#dfcdb7'),false);
// Fridge and a few bright kitchen details.
box(scene,-11.15,1.45,-6.8,1.1,2.8,1.25,material('#e8e5dc'));box(scene,-11.15,2.2,-6.14,1.04,.05,.06,mats.gold,false);box(scene,-11.15,.85,-6.14,1.04,.05,.06,mats.gold,false);
// Living room rug, sofa, table and floor lamp.
const rug=box(scene,3.7,.035,1.1,8.2,.08,5.6,material('#d9bfa0'),false);box(scene,3.7,.082,1.1,7.85,.012,5.25,material('#e8d5bc'),false);
for(let i=0;i<6;i++)box(scene,.35+i*1.35,.094,-1.25,1.1,.008,.035,material('#d1b594'),false);
const sofa=group(scene,5.2,0,-3.15);box(sofa,0,.52,0,5.3,1.05,1.5,mats.sage);box(sofa,0,1.1,-.38,5.3,1.3,.55,mats.sage);box(sofa,-2.58,.85,.05,.4,1.2,1.6,mats.sage);box(sofa,2.58,.85,.05,.4,1.2,1.6,mats.sage);
for(const x of [-1.65,0,1.65]){box(sofa,x,.94,.13,1.48,.18,1.12,material('#a9b39a'));box(sofa,x,.2,.18,.1,.35,.1,mats.oak,false)}
for(const [x,mat] of [[-1.6,mats.pink],[1.45,mats.terracotta]]){const p=box(sofa,x,1.32,-.22,.72,.68,.22,mat);p.rotation.z=-.12}
// Coffee table with favorite knockable clutter.
const table=group(scene,2.9,0,1);box(table,0,.77,0,3.5,.22,2.1,mats.lightOak);for(const x of [-1.45,1.45])for(const z of [-.8,.8])box(table,x,.37,z,.12,.76,.12,mats.oak);
const book=box(table,-.55,.91,-.14,.85,.08,.63,material('#748273'));box(table,-.55,.96,-.14,.73,.02,.52,mats.cream,false);
cylinder(table,.68,1.01,.22,.22,.19,.15,mats.terracotta,20);cylinder(table,.68,.92,.22,.18,.18,.05,mats.cream,20);
// Plant with broad leaves.
const plant=group(scene,7.9,0,-7.15);cylinder(plant,0,.3,0,.55,.42,.6,mats.terracotta);cylinder(plant,0,.62,0,.35,.4,.1,mats.oak);for(let i=0;i<7;i++){const a=i*Math.PI*2/7;const leaf=sphere(plant,Math.cos(a)*.23,.99+(i%3)*.1,Math.sin(a)*.23,.15,.48,.12,mats.green,12);leaf.rotation.z=Math.cos(a)*-.55;leaf.rotation.x=Math.sin(a)*.35}
// Side table and small lamp beside the sofa.
const side=group(scene,9.3,0,-3.1);cylinder(side,0,.64,0,.68,.68,.16,mats.lightOak);cylinder(side,0,.34,0,.09,.13,.5,mats.oak);cylinder(side,0,.09,0,.42,.48,.12,mats.oak);cylinder(side,0,1.18,0,.5,.18,.62,mats.cream);sphere(side,0,1.51,0,.11,.08,.11,mats.gold,12);
// Cat tree/scratching post.
const tree=group(scene,-8.3,0,1.7);cylinder(tree,0,.38,0,.65,.64,.22,mats.terracotta);cylinder(tree,0,1.34,0,.16,.18,1.75,material('#c89c72'));for(let i=0;i<5;i++)cylinder(tree,0,.72+i*.24,0,.19,.19,.035,material('#ead7bd'));box(tree,1.05,1.68,-.1,1.45,.22,1.15,mats.sage);box(tree,1.05,1.85,-.1,1.12,.14,.8,material('#e5d0b1'));cylinder(tree,-.35,2.15,0,.62,.62,.17,mats.terracotta);sphere(tree,-.35,2.32,0,.48,.2,.43,mats.sage);
// Bookshelf along the left wall, books and framed art on the back wall.
const shelf=group(scene,-10.65,0,-1.7);box(shelf,0,1.45,0,2.25,2.9,.55,mats.oak);for(let y of [.5,1.3,2.1,2.8])box(shelf,0,y,.31,2.16,.09,.65,mats.lightOak);
const bookColors=['#cf8468','#d6ae6e','#83927c','#758294','#bf9a8b','#e0c49c'];for(let j=0;j<4;j++)for(let i=0;i<5;i++){const h=.35+(i%3)*.1;const b=box(shelf,-.83+i*.4,.58+h/2,.27,.25,h,.25,material(bookColors[(i+j)%bookColors.length]));b.rotation.z=(i%2?.08:-.04)}
function frame(x,z,color){box(scene,x,2.44,z,.95,1.15,.1,mats.oak);box(scene,x,2.44,z+.065,.79,.96,.035,material('#f5e8d4'),false);sphere(scene,x-.08,2.45,z+.09,.23,.27,.025,material(color),12);box(scene,x+.12,2.2,z+.1,.33,.15,.025,mats.green,false)}
frame(-2.2,-9.12,'#d58d67');frame(1,-9.12,'#82927b');
// Dining nook and plants near the brighter window.
const dining=group(scene,-1.1,0,-5.2);box(dining,0,1.08,0,2.4,.15,1.55,mats.lightOak);for(const x of [-.92,.92])for(const z of [-.55,.55])box(dining,x,.53,z,.1,1,.1,mats.oak);for(const x of [-1.8,1.8]){const chair=group(dining,x,0,.15);box(chair,0,.62,0,.7,.12,.7,mats.terracotta);box(chair,0,1.15,-.28,.7,1,.12,mats.terracotta);for(const xx of [-.27,.27])for(const zz of [-.26,.26])box(chair,xx,.3,zz,.07,.6,.07,mats.oak)}
// Window sill nick-nacks, clock and little framed details.
cylinder(scene,7.75,1.12,-9.02,.2,.2,.17,mats.cream,20);cylinder(scene,7.75,1.12,-8.91,.15,.15,.025,mats.dark,20);

