input.content:
// A toy ball, food nook, sunny perch and familiar house cat.
const ball=group(scene,-2.8,0,2.7);const ballCore=sphere(ball,0,.24,0,.25,.25,.25,mats.terracotta,20);for(let i=0;i<3;i++){const stripe=new THREE.Mesh(new THREE.TorusGeometry(.252,.035,8,24),i===1?mats.cream:mats.gold);stripe.rotation.y=i*Math.PI/3;stripe.position.y=.24;ball.add(stripe)}
const bowl=group(scene,-10.25,0,4.35);cylinder(bowl,0,.2,0,.63,.48,.35,mats.terracotta,20);cylinder(bowl,0,.38,0,.52,.52,.05,mats.gold,20);cylinder(bowl,0,.405,0,.44,.44,.025,material('#b88a5c'),20);for(let i=0;i<11;i++){const a=i*2.4;sphere(bowl,Math.cos(a)*.24,.44+Math.sin(a*.7)*.025,Math.sin(a)*.24,.07,.045,.07,material('#80543a'),10)}
const windowBed=group(scene,5.1,0,-8.25);box(windowBed,0,.4,0,2.7,.34,.95,mats.sage);box(windowBed,0,.62,.03,2.45,.16,.85,material('#e5cbaa'));for(let x of [-1.25,1.25])box(windowBed,x,.2,0,.12,.4,.12,mats.oak);
const cat=group(scene,0,0,5.6);const orange=material('#d9894e'),orangeLight=material('#eaa66a'),creamFur=material('#f2dfbd'),innerEar=material('#bd6b5d'),eyeMat=material('#37433c'),noseMat=material('#ad6757');
const catRig=group(cat);sphere(catRig,0,.53,.07,.39,.39,.62,orange,20);sphere(catRig,0,.45,-.04,.34,.25,.46,orangeLight,18);
const head=group(catRig,0,.82,-.4);sphere(head,0,0,0,.43,.39,.38,orange,20);
// Ears, soft muzzle, expressive eyes, whiskers and nose.
for(const x of [-.29,.29]){const ear=new THREE.Mesh(new THREE.ConeGeometry(.2,.48,4),orange);ear.position.set(x,.34,-.03);ear.rotation.z=x<0?.12:-.12;ear.castShadow=true;head.add(ear);const inside=new THREE.Mesh(new THREE.ConeGeometry(.105,.28,4),innerEar);inside.position.set(x,.34,.045);inside.rotation.z=x<0?.12:-.12;head.add(inside);sphere(head,x*.62,.055,-.325,.115,.145,.055,eyeMat,14);sphere(head,x*.62-.025,.105,-.375,.034,.045,.018,material('#fff9ec'),10)}
sphere(head,0,-.12,-.345,.14,.1,.09,creamFur,14);sphere(head,-.095,-.13,-.32,.11,.08,.08,creamFur,12);sphere(head,.095,-.13,-.32,.11,.08,.08,creamFur,12);sphere(head,0,-.065,-.425,.055,.04,.035,noseMat,12);
for(const sideSign of [-1,1])for(let i=0;i<2;i++){const w=box(head,sideSign*.31,-.14-i*.045,-.32,.24,.012,.012,creamFur,false);w.rotation.z=sideSign*.12}
// Feet and paws; legs swing with a light little trot.
const legs=[];for(const x of [-.25,.25])for(const z of [-.32,.4]){const leg=group(catRig,x,.35,z);cylinder(leg,0,-.085,0,.105,.12,.28,orange,12);sphere(leg,0,-.21,-.035,.13,.09,.16,orangeLight,12);legs.push(leg)}
// Animated, curved tail built from three smooth links.
const tailJoints=[];let previous=null;for(let i=0;i<7;i++){const link=sphere(catRig,0,.61,.58+i*.2,.125-i*.009,.125-i*.009,.18,orange,12);tailJoints.push(link)}
// Distinct collar and tiny bell.
const collar=new THREE.Mesh(new THREE.TorusGeometry(.245,.035,8,24),material('#89a08a'));collar.rotation.x=Math.PI/2;collar.position.set(0,.66,-.28);catRig.add(collar);sphere(catRig,0,.57,-.48,.055,.065,.05,mats.gold,12);

const $=s=>document.querySelector(s);const toastEl=$('#toast'),interactionEl=$('#interaction');let happy=78,curiosity=62,memories=[],lastTime=performance.now(),walkTime=0,pounceUntil=0,held=new Set(),mobileHeld=new Set(),nearby=null,toastTimer;
const interactions=[
 {name:'Sunny window',x:5.1,z:-8.05,r:2.1,verb:'Climb up',icon:'☀',title:'A perfect sunbeam',text:'You found the warmest spot in the house.',run:()=>{cat.position.set(5.1,0,-7.15);cat.rotation.y=Math.PI;return 'You curl up in the golden sunbeam.'}},
 {name:'Sofa',x:5.2,z:-3.1,r:2.5,verb:'Take a nap',icon:'☾',title:'Sofa snooze',text:'A soft cushion and absolutely no plans.',run:()=>nap('The sofa is extra-soft today.')},
 {name:'Scratching post',x:-8.3,z:1.7,r:2.3,verb:'Scratch away',icon:'✧',title:'Claw-some!',text:'The scratch post is looking very well-loved.',run:()=>{cat.rotation.y=1.3;return 'Stretch, scratch, and feel fabulous.'}},
 {name:'Food bowl',x:-10.25,z:4.35,r:2.1,verb:'Have a snack',icon:'♥',title:'A little snack',text:'Crunchy snacks make a very happy cat.',run:()=>{happy=Math.min(100,happy+11);return 'Crunch crunch. Delicious.'}},
 {name:'Potted plant',x:7.9,z:-7.15,r:2.2,verb:'Investigate',icon:'♧',title:'Botanical investigations',text:'The leaves have been thoroughly inspected.',run:()=>{const p=plant.rotation;p.y+=.4;return 'A suspicious leaf. Better sniff it again.'}},
 {name:'Bookshelf',x:-10.65,z:-1.7,r:2.1,verb:'Explore',icon:'⌂',title:'Shelf supervisor',text:'Every book is right where it should be (mostly).',run:()=>{happy=Math.min(100,happy+5);return 'You inspect the shelves with great authority.'}},
 {name:'Coffee table',x:2.9,z:1,r:2.1,verb:'Cause mischief',icon:'↗',title:'Table-top trouble',text:'Something has been nudged. Who could it be?',run:()=>{const bx=table.position.x+1.1,bz=table.position.z;cat.rotation.y=1.2;book.rotation.z=.35;book.position.x+=.38;setTimeout(()=>{book.position.x=-.55;book.rotation.z=0},8000);happy=Math.min(100,happy+7);return 'A gentle paw. A not-so-gentle clatter.'}},
 {name:'Kitchen',x:-8,z:-5.7,r:2.4,verb:'Have a look',icon:'⌂',title:'Kitchen patrol',text:'Nothing escapes a very observant cat.',run:()=>{curiosity=Math.min(100,curiosity+10);return 'You patrol the kitchen for important crumbs.'}},
 {name:'Toy ball',x:-2.8,z:2.7,r:2.2,verb:'Bat the toy',icon:'✦',title:'Playtime!',text:'The little ball went skittering across the floor.',run:()=>{ball.position.x+=(Math.random()-.5)*3;ball.position.z+=(Math.random()-.5)*3;ball.position.x=THREE.MathUtils.clamp(ball.position.x,-6,6);ball.position.z=THREE.MathUtils.clamp(ball.position.z,-5,6);happy=Math.min(100,happy+9);curiosity=Math.min(100,curiosity+8);return 'Bap! The ball rolls away. Again!'}},
 {name:'Dining chair',x:-1.1,z:-5,r:2.2,verb:'Hop on',icon:'↑',title:'A higher perspective',text:'The dining table looks very interesting from here.',run:()=>{cat.position.set(-1.1,0,-4.5);return 'Up you go. The whole room is yours.'}}
];
function nap(msg){catRig.rotation.x=-.24;setTimeout(()=>catRig.rotation.x=0,1600);happy=Math.min(100,happy+8);return msg}
function showToast(message){toastEl.textContent=message;toastEl.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>toastEl.classList.remove('show'),2500)}
function saveMemory(item){if(memories.some(m=>m.title===item.title)){showToast(item.text);return}memories.unshift({title:item.title,text:item.text,icon:item.icon});$('#moment-count').textContent=memories.length;const list=$('#memory-list');list.innerHTML=memories.map(m=>`<div class="memory-item"><span>${m.icon}</span><div><b>${m.title}</b><small>${m.text}</small></div></div>`).join('');showToast(item.text);$('#activity-title').textContent=item.title;$('#activity-text').textContent=item.text}
function refreshNeeds(){happy=Math.max(15,happy-.002);curiosity=Math.max(15,curiosity-.004);$('#happy-meter').style.width=`${happy}%`;$('#happy-label').textContent=`${Math.round(happy)}%`;$('#curiosity-meter').style.width=`${curiosity}%`;$('#curiosity-label').textContent=`${Math.round(curiosity)}%`}
function getNearby(){let best=null,dist=Infinity;for(const item of interactions){const d=Math.hypot(cat.position.x-item.x,cat.position.z-item.z);if(d<item.r&&d<dist){best=item;dist=d}}return best}
function doInteract(){if(!started)return;const item=getNearby();if(item){const result=item.run();saveMemory(item);showToast(result)}else{happy=Math.min(100,happy+1);showToast('A soft purr. Nothing you need to do right now.')}}

// House movement and interactive camera controls.
function pointerDown(e){if(e.target.closest('button,.journal-modal'))return;pointer={x:e.clientX,y:e.clientY,moved:false};canvas.setPointerCapture?.(e.pointerId)}let pointer=null;
