 for(let i=0;i<tailJoints.length;i++){const q=i/6;tailJoints[i].position.x=Math.sin(t*.002+i*.35)*(.06+q*.14);tailJoints[i].position.y=.61+q*.42+Math.sin(t*.0022+i*.42)*(.035+q*.06);tailJoints[i].position.z=.58+q*.21}}
