content.text:
.mobile-controls{display:none;position:absolute;bottom:16px;left:16px;right:16px;z-index:4;justify-content:space-between;align-items:flex-end;pointer-events:none}
.dpad,.mobile-actions{pointer-events:auto}
.dpad button,.mobile-actions button{border:1px solid #ffffffa8;background:#fffaf1d9;backdrop-filter:blur(6px);box-shadow:0 4px 12px #3c332a30;color:#61594d;border-radius:12px;width:42px;height:42px;font-size:15px;touch-action:none}
.dpad>button{display:block;margin:auto auto 3px}
.dpad>div{display:flex;gap:3px}
.mobile-actions{display:flex;gap:8px}
.mobile-actions button{width:51px;height:51px;font-size:15px;color:#cf8756}
.mobile-actions small{display:block;font:600 8px 'DM Sans';color:#776e60}
@media(max-width:720px){.topbar{padding:14px 15px}
.mobile-controls{display:flex}
@media(max-width:410px){.day-pill{gap:5px}
.mobile-controls{bottom:12px}
.dpad button,.mobile-actions button{width:39px;height:39px}
.mobile-actions button{width:46px;height:46px}
@media(hover:none){.mobile-controls{display:flex}

*{box-sizing:border-box}
 :root{--ink:#38352f;--muted:#878176;--cream:#fffaf1;--orange:#e18b55;--line:rgba(78,66,50,.12)}
html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#e8dfd0;color:var(--ink);font-family:'DM Sans',sans-serif}
button{font:inherit;color:inherit}
#game-shell{position:relative;width:100%;height:100%;overflow:hidden;background:#d9c9b2}
#game{position:absolute;inset:0;width:100%;height:100%;display:block;touch-action:none}
.vignette{position:absolute;inset:0;pointer-events:none;background:linear-gradient(180deg,rgba(37,34,29,.22),transparent 19%,transparent 73%,rgba(35,32,28,.2)),linear-gradient(90deg,rgba(35,32,28,.12),transparent 22%,transparent 85%,rgba(35,32,28,.08))}
.topbar{position:absolute;left:0;right:0;top:0;padding:24px 32px;display:flex;align-items:center;gap:18px;color:#fff;z-index:2}
.brand{display:flex;align-items:center;gap:12px;margin-right:auto;text-shadow:0 1px 9px #544b3c70}
.brand-icon{width:42px;height:42px;border-radius:15px;background:#fff3e4;color:#a86a41;display:grid;place-items:center;font-size:21px;text-shadow:none;box-shadow:0 5px 15px #38332c20}
.brand-title{font:700 19px 'Fraunces',serif;letter-spacing:-.3px}
.brand-title span{font-weight:600}
.brand-subtitle{font-size:11px;opacity:.82;margin-top:1px;letter-spacing:.2px}
.day-pill{height:36px;border:1px solid #ffffff50;border-radius:22px;background:#39372f42;backdrop-filter:blur(8px);display:flex;align-items:center;gap:9px;padding:0 14px;font-size:11px;color:#fff}
.day-pill i{height:3px;width:3px;background:#fff;border-radius:50%;opacity:.8}
.sun-icon{font-size:14px;color:#ffe0a6}
.icon-button{border:1px solid #ffffff50;background:#39372f42;color:#fff;border-radius:50%;width:36px;height:36px;cursor:pointer;font-size:16px;backdrop-filter:blur(8px)}
.welcome-card{position:absolute;top:50%;left:7.3%;transform:translateY(-42%);z-index:2;width:315px;padding:0 0 0 3px;color:#fff;text-shadow:0 2px 18px #37312870;transition:opacity .55s,transform .55s}
.eyebrow{font-size:9px;font-weight:700;letter-spacing:1.75px;display:flex;align-items:center;gap:8px;color:#f8e6d0}
.eyebrow span{width:6px;height:6px;border-radius:50%;background:#eda973;box-shadow:0 0 0 4px #eda97328}
.welcome-card h1{font:600 52px/.99 'Fraunces',serif;letter-spacing:-1.6px;margin:17px 0 13px}
.welcome-card h1 em{font-weight:600;color:#ffdbad}
.welcome-card p{font-size:13px;line-height:1.75;color:#fff9f0;margin:0 0 22px}
.primary-button{background:#fffaf2;border:0;border-radius:8px;padding:12px 17px;color:#4e4539;font-size:12px;font-weight:700;display:flex;align-items:center;gap:25px;box-shadow:0 8px 26px #493b2c37;cursor:pointer;transition:transform .2s,background .2s}
.primary-button:hover{transform:translateY(-2px);background:#fff}
.primary-button span{font-size:17px;color:#ce8253}
.welcome-foot{margin-top:23px;font-size:10px;color:#fff9f0aa}
.welcome-foot span{color:#ffd69d;margin-right:5px}
.needs-card{position:absolute;right:30px;top:86px;width:226px;background:#fffaf1ed;border:1px solid #fff9;border-radius:13px;padding:15px 15px 13px;z-index:2;box-shadow:0 10px 32px #50433623;backdrop-filter:blur(8px);transition:opacity .4s,transform .4s}
.needs-title{font-size:8px;font-weight:700;letter-spacing:1.2px;color:#a59a89;margin-bottom:12px}
.needs-title span{float:right;color:#e5a56f;font-size:11px}
.cat-name{display:flex;align-items:center;gap:9px;margin-bottom:13px}
.cat-avatar{width:35px;height:35px;border-radius:11px;background:#f5e1c9;display:grid;place-items:center;font-size:20px}
.cat-name b,.cat-name small{display:block}
.cat-name b{font:600 14px 'Fraunces',serif}
.cat-name small{font-size:9px;color:#a19a8f;margin-top:2px}
.mood{margin-left:auto;color:#df9667;font-size:20px}
.need-row{display:flex;align-items:center;font-size:9px;color:#858075;gap:7px;margin:8px 0}
.need-row b{font-size:9px;color:#5e594f;font-weight:600;width:25px;text-align:right}
.meter{height:5px;background:#ece7df;border-radius:8px;flex:1;overflow:hidden}
.meter i{height:100%;display:block;width:78%;border-radius:8px;background:#e5a273;transition:width .5s}
.meter.curiosity i{background:#94a78a;width:62%}
.discovery{border-top:1px solid #eee8dd;margin-top:13px;padding-top:11px;display:flex;gap:8px;align-items:flex-start}
.sparkle{font-size:13px;color:#d99462}
.discovery b,.discovery small{display:block}
.discovery b{font:600 11px 'Fraunces',serif}
.discovery small{font-size:9px;color:#999184;margin-top:3px;line-height:1.35}
.location-chip{position:absolute;left:50%;top:20px;transform:translateX(-50%);z-index:2;background:#39372f4d;color:#fff;border:1px solid #ffffff45;border-radius:20px;padding:7px 12px;font-size:8px;font-weight:700;letter-spacing:1.4px;backdrop-filter:blur(8px);opacity:0;transition:opacity .4s}
.location-dot{display:inline-block;width:5px;height:5px;border-radius:50%;background:#f1b276;margin-right:6px;vertical-align:1px}
.interaction{position:absolute;left:50%;bottom:138px;transform:translateX(-50%) translateY(8px);z-index:3;display:flex;align-items:center;gap:8px;background:#37342ecc;color:#fff;border:1px solid #ffffff30;border-radius:7px;padding:7px 11px;font-size:11px;opacity:0;pointer-events:none;transition:opacity .2s,transform .2s;white-space:nowrap;backdrop-filter:blur(6px)}
.interaction.visible{opacity:1;transform:translateX(-50%) translateY(0)}
.keycap{background:#fffaf1;color:#575044;border-radius:4px;padding:3px 6px;font-weight:700;font-size:9px}
.bottom-ui{position:absolute;bottom:24px;left:30px;right:30px;z-index:2;display:flex;align-items:flex-end;justify-content:space-between;transition:opacity .4s}
.controls-card{height:62px;background:#fffaf1ed;border:1px solid #fff;border-radius:11px;box-shadow:0 8px 24px #44382a26;display:flex;align-items:center;padding:0 14px;gap:14px;backdrop-filter:blur(8px)}
.control-group{display:flex;align-items:center;gap:8px;color:#898174;font-size:9px;white-space:nowrap}
.keys{display:flex;flex-direction:column;align-items:center;gap:2px}
.keys div{display:flex;gap:2px}
.keys kbd,.single-key{background:#f1ece3;border:1px solid #e6dfd4;border-bottom-width:2px;border-radius:4px;min-width:17px;height:15px;display:inline-grid;place-items:center;font:700 8px 'DM Sans';color:#6b6254}
.single-key{height:20px;padding:0 6px;min-width:auto;font-size:8px}
.divider{height:27px;width:1px;background:#e8e1d7}
.drag-hint{margin-left:2px;color:#aaa092;font-size:8px;letter-spacing:1px;white-space:nowrap}
.drag-hint span{font-size:14px;color:#d49368;margin-left:4px}
.journal-button{height:56px;border:1px solid #ffffffa6;border-radius:10px;background:#fffaf1ed;padding:0 13px;display:flex;align-items:center;gap:10px;text-align:left;box-shadow:0 8px 24px #44382a26;cursor:pointer;backdrop-filter:blur(8px)}
.journal-button>span:first-child{color:#d89462;font-size:18px}
.journal-button b,.journal-button small{display:block}
.journal-button b{font:600 12px 'Fraunces',serif}
.journal-button small{color:#999184;font-size:9px;margin-top:2px}
.journal-arrow{font-size:14px;color:#b1a595;margin-left:13px}
.mobile-controls{display:none;position:absolute;bottom:16px;left:16px;right:16px;z-index:4;justify-content:space-between;align-items:flex-end;pointer-events:none}
.dpad,.mobile-actions{pointer-events:auto}
.dpad button,.mobile-actions button{border:1px solid #ffffffa8;background:#fffaf1d9;backdrop-filter:blur(6px);box-shadow:0 4px 12px #3c332a30;color:#61594d;border-radius:12px;width:42px;height:42px;font-size:15px;touch-action:none}
.dpad>button{display:block;margin:auto auto 3px}
.dpad>div{display:flex;gap:3px}
.mobile-actions{display:flex;gap:8px}
.mobile-actions button{width:51px;height:51px;font-size:15px;color:#cf8756}
.mobile-actions small{display:block;font:600 8px 'DM Sans';color:#776e60}
.toast{position:absolute;top:74px;left:50%;z-index:5;transform:translate(-50%,-12px);background:#39372fe8;color:#fff;border-radius:20px;padding:9px 15px;font-size:11px;box-shadow:0 5px 20px #39372f40;opacity:0;transition:.3s;pointer-events:none;white-space:nowrap}
.toast.show{opacity:1;transform:translate(-50%,0)}
.modal-backdrop{position:absolute;inset:0;background:#29251f77;z-index:8;display:grid;place-items:center;opacity:0;pointer-events:none;transition:opacity .25s;backdrop-filter:blur(3px)}
.modal-backdrop.open{opacity:1;pointer-events:auto}
.journal-modal{position:relative;background:#fffaf2;width:min(410px,calc(100% - 34px));border-radius:17px;padding:27px 28px 25px;box-shadow:0 25px 80px #29251f55;transform:translateY(12px);transition:transform .25s}
.open .journal-modal{transform:translateY(0)}
.journal-modal .eyebrow{color:#a39786}
.journal-modal h2{font:600 31px 'Fraunces',serif;margin:13px 0 5px;letter-spacing:-.5px}
.journal-intro{font-size:11px;color:#928a7d;margin:0 0 19px}
.modal-close{position:absolute;right:16px;top:13px;border:0;background:none;font-size:24px;color:#958b7e;cursor:pointer}
.memory-list{max-height:250px;overflow:auto}
.memory-empty{text-align:center;padding:26px 8px;color:#a49a8b;font-size:11px;line-height:1.6}
.memory-empty span{display:block;font-size:24px;margin-bottom:9px}
.memory-item{display:flex;gap:10px;padding:10px 0;border-top:1px solid #eee8df;align-items:center}
.memory-item>span{width:32px;height:32px;border-radius:10px;background:#f5e8d6;display:grid;place-items:center}
.memory-item b,.memory-item small{display:block}
.memory-item b{font:600 12px 'Fraunces',serif}
.memory-item small{font-size:9px;color:#9e9689;margin-top:3px}
.loading{position:absolute;inset:0;background:#eee3d2;z-index:20;display:flex;align-items:center;justify-content:center;flex-direction:column;transition:opacity .6s}
.loading.done{opacity:0;pointer-events:none}
.loader-paw{font-size:31px;animation:bop .8s infinite alternate}
.loading p{font:600 13px 'Fraunces',serif;color:#807665}
@keyframes bop{to{transform:translateY(-8px) rotate(9deg)}
}
.started .welcome-card{opacity:0;transform:translate(-20px,-42%);pointer-events:none}
.started .needs-card{transform:translateY(-5px)}
.started .location-chip{opacity:1}
.started .bottom-ui{opacity:1}
@media(max-width:720px){.topbar{padding:14px 15px}
.brand-icon{width:36px;height:36px}
.brand-title{font-size:16px}
.brand-subtitle{font-size:9px}
.day-pill{padding:0 10px;font-size:9px;gap:6px}
.icon-button{width:33px;height:33px}
.welcome-card{left:7%;top:43%;width:280px}
.welcome-card h1{font-size:44px}
.needs-card{top:68px;right:12px;width:190px;padding:12px}
.needs-title{font-size:7px;margin-bottom:8px}
.cat-name{margin-bottom:9px}
.discovery{margin-top:9px;padding-top:8px}
.bottom-ui{left:12px;right:12px;bottom:13px}
.controls-card{display:none}
.journal-button{height:47px;padding:0 10px}
.journal-arrow{margin-left:4px}
.mobile-controls{display:flex}
.interaction{bottom:111px}
.location-chip{top:62px;font-size:7px}
.toast{top:62px}
.welcome-foot{margin-top:15px}
.welcome-card p{font-size:12px}
.welcome-card h1{margin-top:12px}
.welcome-card .primary-button{padding:10px 14px}
}
@media(max-width:410px){.day-pill{gap:5px}
.day-pill span:first-child{display:none}
.needs-card{width:173px;right:9px;top:64px}
.welcome-card{top:42%;width:250px}
.welcome-card h1{font-size:39px}
.welcome-card p{font-size:11px}
.mobile-controls{bottom:12px}
.dpad button,.mobile-actions button{width:39px;height:39px}
.mobile-actions button{width:46px;height:46px}
.journal-button{transform:scale(.92);transform-origin:right bottom}
}
@media(hover:none){.mobile-controls{display:flex}
.controls-card{display:none}
}

