const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
(async()=>{
 const browser=await chromium.launch({headless:true,args:['--no-sandbox','--use-gl=angle','--use-angle=swiftshader','--enable-webgl']});
 const page=await browser.newPage({viewport:{width:390,height:844},deviceScaleFactor:1,isMobile:true,hasTouch:true});
 const errors=[];page.on('pageerror',e=>errors.push(e.message));
 await page.goto('http://127.0.0.1:8787',{waitUntil:'networkidle',timeout:60000});
 await page.waitForTimeout(1000);
 const joystickVisible=await page.locator('#joystick').isVisible();
 await page.locator('#start-btn').click();
 await page.waitForTimeout(800);
 await page.locator('#mobile-meow').click();
 const meowToast=await page.locator('#toast').innerText();
 await page.locator('#mobile-run').click();
 const runActive=await page.locator('#mobile-run').evaluate(e=>e.classList.contains('active'));
 const box=await page.locator('#joystick').boundingBox();
 await page.mouse.move(box.x+box.width/2,box.y+box.height/2);
 await page.mouse.down();await page.mouse.move(box.x+box.width/2,box.y+box.height*.22,{steps:4});
 await page.waitForTimeout(700);await page.mouse.up();
 await page.locator('#journal-btn').click();
 const scrapbookOpen=await page.locator('#modal-backdrop').evaluate(e=>e.classList.contains('open'));
 await page.locator('#modal-close').click();
 await page.waitForTimeout(200);
 await page.screenshot({path:'/tmp/opencode/catgame-current.jpg',type:'jpeg',quality:68});
 console.log(JSON.stringify({joystickVisible,meowToast,runActive,scrapbookOpen,errors},null,2));
 await browser.close();
})().catch(e=>{console.error(e);process.exit(1)});

