const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
(async()=>{
  const browser = await chromium.launch({
    headless: true,
    args: ['--no-sandbox','--use-gl=angle','--use-angle=swiftshader','--enable-webgl']
  });
  const page = await browser.newPage({
    viewport: { width: 390, height: 844 },
    deviceScaleFactor: 1,
    isMobile: true,
    hasTouch: true,
    userAgent: 'Mozilla/5.0 (iPhone; CPU iPhone OS 17_0 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/17.0 Mobile/15E148 Safari/604.1'
  });
  const errors = [];
  page.on('pageerror', e => errors.push(e.message));
  page.on('console', msg => {
    if (msg.type() === 'error') errors.push(`console:${msg.text()}`);
  });

  await page.goto('http://127.0.0.1:8787', { waitUntil: 'networkidle', timeout: 60000 });
  await page.waitForTimeout(1200);

  const startVisible = await page.locator('#start-btn').isVisible();
  await page.locator('#start-btn').click();
  await page.waitForTimeout(500);

  const joystickVisible = await page.locator('#joystick').isVisible();
  await page.locator('#mobile-meow').click();
  const meowText = await page.locator('#toast').innerText();

  await page.locator('#mobile-run').click();
  const runActive = await page.locator('#mobile-run').evaluate(el => el.classList.contains('active'));

  const joystickBox = await page.locator('#joystick').boundingBox();
  if (joystickBox) {
    await page.mouse.move(joystickBox.x + joystickBox.width * 0.5, joystickBox.y + joystickBox.height * 0.5);
    await page.mouse.down();
    await page.mouse.move(joystickBox.x + joystickBox.width * 0.5, joystickBox.y + joystickBox.height * 0.2, { steps: 8 });
    await page.waitForTimeout(500);
    await page.mouse.up();
  }

  await page.locator('#journal-btn').click();
  const scrapbookOpen = await page.locator('#modal-backdrop').evaluate(el => el.classList.contains('open'));
  await page.locator('#modal-close').click();
  await page.waitForTimeout(250);

  await page.screenshot({ path: '/tmp/opencode/catgame-current.jpg', type: 'jpeg', quality: 68 });

  console.log(JSON.stringify({
    startVisible,
    joystickVisible,
    meowText,
    runActive,
    scrapbookOpen,
    errors
  }, null, 2));

  await browser.close();
})().catch(err => {
  console.error(err);
  process.exit(1);
});

